import type { WorkflowInput } from "../types/workflow-input.js";
import {commonEvent,mapEvent,showPicture,imageAsset,callCommonEvent,commonEventRef,showAnimation,animationRef,changeTileset,tilesetRef} from "rpgmaker-event-dsl";
export const event=commonEvent({id:10,name:"Workflow",trigger:"none",commands:[showPicture({pictureId:1,image:imageAsset({folder:"pictures",name:"Poster"}),origin:"upperLeft",position:{kind:"direct",x:0,y:0},scaleX:100,scaleY:100,opacity:255,blendMode:"normal"})]});

