import type { WorkflowInput } from "../types/workflow-input.js";
import {commonEvent,mapEvent,showPicture,imageAsset,callCommonEvent,commonEventRef,showAnimation,animationRef,changeTileset,tilesetRef} from "rpgmaker-event-dsl";
export const event=mapEvent({mapId:1,id:1,name:"Workflow",x:0,y:0,pages:[{conditions:{},trigger:"action",commands:[],movement:{type:"fixed",route:{commands:[{kind:"changeImage",character:imageAsset({folder:"characters",name:"Poster"}),characterIndex:0}]}}}]});

