  };
} | {
  kind: "character";
  target: CharacterRuntimeSelector;
  direction: 2 | 4 | 6 | 8;
} | {
  kind: "gold";
  amount: number;
  operator: "ge" | "le" | "lt";
} | {
  kind: "item";
